export function buildRegionalWorld({scene,register,block,mats,mobile=false,save=()=>{},loadAnimals=true}){
 const farms=new Map(),unit=new T.BoxGeometry(1,1,1),materials=new Map();
 function cube(parent,w,h,d,c,x,y,z){if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.93}));const o=new T.Mesh(unit,materials.get(c));o.scale.set(w,h,d);o.position.set(x,y,z);o.receiveShadow=true;parent.add(o);return o;}
 const terrainGeo=new T.PlaneGeometry(2000,1800,48,44);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),out=Math.max(0,Math.abs(x-6)-272,Math.abs(z)-244);pos.setY(i,-.12+Math.min(75,out*.13)*(1+.25*Math.sin(x*.016)*Math.cos(z*.019)));}terrainGeo.computeVertexNormals();const terrain=new T.Mesh(terrainGeo,new T.MeshStandardMaterial({color:'#849d6c',map:mats.grass.map,roughness:1}));terrain.name='Continuous rolling horizon';terrain.receiveShadow=true;scene.add(terrain);
 function label(g,text,x,y,z){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;const c=canvas.getContext('2d');c.fillStyle='#f7efdb';c.fillRect?.(0,0,512,96);c.fillStyle='#344f3c';c.font='bold 25px system-ui';c.textAlign='center';c.fillText(text,256,60);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(canvas)}));s.position.set(x,y,z);s.scale.set(12,2.25,1);g.add(s);}
 for(const p of FARMS){const plan=farmLayout(p),root=new T.Group();root.name=p.name;scene.add(root);const station={kind:'regionalFarm',farmId:p.id,x:p.x,z:p.z,approach:p.approach};
  for(const b of plan.buildings){const building=buildNeighbourBuilding(b,p);root.add(building);register(building,station);}
  for(const b of plan.blocks)block(b.x,b.z,b.w,b.d);
  cube(root,5,.05,p.approach.z-p.z+23,'#c2b495',p.x,.24,(p.approach.z+p.z-23)/2);
  label(root,p.name.toUpperCase(),p.x,10,p.z+23);const post=cube(root,2.6,1.6,.15,'#e8dcc1',p.approach.x,.99,p.approach.z-3);register(post,station);
  if(plan.pen){cube(root,plan.pen.maxX-plan.pen.minX,.04,plan.pen.maxZ-plan.pen.minZ,'#a6b77e',(plan.pen.minX+plan.pen.maxX)/2,.24,(plan.pen.minZ+plan.pen.maxZ)/2);for(const f of plan.fences){for(const y of [.7,1.25])cube(root,f.w,.12,f.d,'#c3b18c',f.x,y,f.z);const length=Math.max(f.w,f.d);for(let t=-length/2;t<=length/2;t+=3){cube(root,.13,1.25,.13,'#a48e68',f.x+(f.w>f.d?t:0),.85,f.z+(f.d>f.w?t:0));}}}
  for(const [i,t]of [...plan.troughs,...plan.petBowls].entries()){if(t.w<1){const bowl=new T.Mesh(new T.CylinderGeometry(.32,.27,.13,16),new T.MeshStandardMaterial({color:'#7c9796',roughness:.7}));bowl.position.set(t.x,.325,t.z);root.add(bowl);const food=new T.Mesh(new T.CircleGeometry(.27,16),new T.MeshStandardMaterial({color:i%2?'#78a5b0':'#cbb16f'}));food.rotation.x=-Math.PI/2;food.position.set(t.x,.395,t.z);root.add(food);}else{cube(root,t.w,.45,t.d,'#ad9470',t.x,.48,t.z);cube(root,t.w-.15,.06,t.d-.15,i%2?'#7cacb6':'#d1b779',t.x,.74,t.z);}register(root.children.at(-1),station);}
  const growth=new T.Group(),gardens=new T.Group();root.add(growth,gardens);gardens.userData.dynamicGrowth=true;for(const [i,g]of plan.gardens.entries()){cube(root,g.w,.06,g.d,'#74553a',g.x,.27,g.z);const crop=gardenCrop(g,i);gardens.add(crop);plan.blocks.push({...g});block(g.x,g.z,g.w,g.d);}if(plan.fields){const f=plan.fields;cube(root,f.w,.05,f.d,'#84654a',f.x,.25,f.z);for(let i=0;i<8;i++)cube(root,f.w-.5,.025,.18,'#68513c',f.x,.29,f.z-f.d/2+2+i*(f.d-4)/7);growth.add(createFieldCrop(f.x,f.z,f.w,f.d));}
  if(p.kind==='boarding'){const sand=new T.Mesh(new T.CircleGeometry(1,48),new T.MeshStandardMaterial({color:'#c3ad87',roughness:1}));sand.rotation.x=-Math.PI/2;sand.scale.set(9.5,11.8,1);sand.position.set(p.x-16.5,.28,p.z+6);root.add(sand);label(root,'TURNOUT & LUNGING RING',p.x-16,3,p.z+17);}
  if(p.kind==='dairy'||p.kind==='crop'){const x=p.x+25,z=p.z+15,r=p.kind==='dairy'?1.15:1.4,tank=new T.Mesh(new T.CylinderGeometry(r,r,4,16),new T.MeshStandardMaterial({color:'#bac6c0',metalness:.25,roughness:.55}));tank.position.set(x,2.25,z);root.add(tank);plan.blocks.push({x,z,w:r*2,d:r*2});block(x,z,r*2,r*2);}
  let orchard;if(p.kind!=='orchard'){orchard=createOrchard(p.x-17,p.z+24,{rows:1,cols:3,spacing:5});root.add(orchard.root);for(const t of orchard.trees){const b={x:t.tree.position.x,z:t.tree.position.z,w:.7,d:.7};plan.blocks.push(b);block(b.x,b.z,b.w,b.d);}}if(p.kind==='orchard'){orchard=createOrchard(p.x-17,p.z+2,{rows:3,cols:4,spacing:4.5});root.add(orchard.root);for(let row=0;row<3;row++)for(let col=0;col<4;col++){const b={x:p.x-17+(col-1.5)*4.5,z:p.z+2+(row-1)*6.3,w:.6,d:.6};plan.blocks.push(b);block(b.x,b.z,b.w,b.d);}}
  if(p.premium){const tank=new T.Mesh(new T.CylinderGeometry(1.8,1.8,4,16),new T.MeshStandardMaterial({color:'#a4b7b3',roughness:.65,metalness:.2}));tank.position.set(p.x+25,2.2,p.z+20);root.add(tank);block(p.x+25,p.z+20,3.6,3.6);plan.blocks.push({x:p.x+25,z:p.z+20,w:4,d:4});}
  treeGrove(root,p.x+24,p.z-23,3,3);for(let i=0;i<3;i++){const b={x:p.x+24+Math.sin(i*4.1)*3,z:p.z-23+Math.cos(i*3.7)*2.1,w:.65,d:.65};plan.blocks.push(b);block(b.x,b.z,b.w,b.d);}growth.userData.dynamicGrowth=true;if(orchard)orchard.root.userData.dynamicGrowth=true;const inGrowth=o=>{for(let a=o.parent;a;a=a.parent)if(a.userData.dynamicGrowth)return true;return false;};root.updateMatrixWorld(true);const buckets=new Map(),remove=[];root.traverse(o=>{if(o.isMesh&&!o.isInstancedMesh&&!inGrowth(o)){const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrixWorld);if(!buckets.has(o.material))buckets.set(o.material,[]);buckets.get(o.material).push(geo);remove.push(o);}});for(const o of remove){o.visible=false;o.removeFromParent();}for(const [mat,list]of buckets){const mesh=new T.Mesh(mergeGeometries(list),mat);mesh.receiveShadow=true;root.add(mesh);for(const g of list)g.dispose();}register(root,station);farms.set(p.id,{root,plan,growth,orchard,loaded:false,animals:[],people:createFarmResidents({parent:root,p,plan,register,load:false})});
 }
 function populate(p,v,state){if(loadAnimals)v.people.loadModels();v.loaded=true;if(!loadAnimals)return;
  for(const [i,type]of v.plan.animals.entries()){const zone=v.plan.zones.pasture,x=p.x-23+i*5,z=p.z+2+i*3,g=new T.Group();g.position.set(p.x-23+(i%3)*5,.2,p.z+2+Math.floor(i/3)*7);v.root.add(g);const key='regional-'+p.id+'-'+i,agent=createAgent(key,g.position.x,g.position.z,zone,{radius:type==='horse'?1.65:type==='cow'?1.45:.9,speed:type==='pig'?.65:.9});g.userData={type,name:p.name+' '+type+' '+(i+1),appearanceKey:key};let legs=[];if(type==='chicken')legs=neighbourHen(g,i);else{const body=new T.Mesh(new T.SphereGeometry(1,10,8),new T.MeshStandardMaterial({color:'#b4a48a'}));body.scale.set(.55,.65,1);body.position.y=1;g.add(body);}v.animals.push({g,type,legs,agent,walkPhase:agent.phase,animationOffset:agent.phase,animationRate:agent.rate,appearanceSlot:animalIdentity(state,type,key,i).coatId});}
  v.modelStatus='Loading farm residents';upgradeAnimals(v.animals,()=>{for(const a of v.animals)if(a.model&&!a.registered){register(a.model,{kind:'regionalFarm',farmId:p.id,x:p.x,z:p.z,approach:p.approach});a.registered=true;}}).then(()=>{v.modelStatus=v.animals.every(a=>a.nativeRig)?'animated models loaded · neighbours active':'Some animal models unavailable';save();});
 }
 return {farms,terrain,update(dt,player,state,focus=player){const own=ensureFarms(state).owned,nearest=[...FARMS].sort((a,b)=>Math.hypot(player.x-a.x,player.z-a.z)-Math.hypot(player.x-b.x,player.z-b.z)).slice(0,mobile?2:3).map(p=>p.id);
  for(const p of FARMS){const v=farms.get(p.id),d=Math.min(Math.hypot(player.x-p.x,player.z-p.z),Math.hypot(focus.x-p.x,focus.z-p.z));if(d<(mobile?80:125)&&!v.loaded)populate(p,v,state);v.root.visible=d<(mobile?290:420);v.growth.visible=!own[p.id]||!!own[p.id]?.job;v.growth.scale.y=!own[p.id]? .75:.04+.96*growthProgress(own[p.id]?.job,state.day);v.growth.position.y=.3*(1-v.growth.scale.y);v.orchard?.update(own[p.id]?{...own[p.id],established:true}:{established:true,job:{startedAt:Date.now()-48*3600000,durationMs:72*3600000,startedDay:state.day,readyDay:state.day+3}},state.day);
   const detailVisible=d<(mobile?95:155);for(const r of v.people?.residents||[]){if(!r.travel)r.root.visible=detailVisible&&r.isOutside!==false;if(r.ball&&!detailVisible)r.ball.visible=false;}for(const r of v.people?.pets||[])r.model.root.visible=detailVisible;for(const a of v.animals)a.g.visible=detailVisible;const active=d<(mobile?65:100)&&(nearest.includes(p.id)||Math.hypot(focus.x-p.x,focus.z-p.z)<35);if(!active)continue;v.simTime=(v.simTime||0)+dt;if(v.simTime<(mobile?.1:.067))continue;const stepDt=v.simTime;v.simTime=0;const others=[...(v.people?.residents||[]),...(v.people?.pets||[])].map(r=>r.agent),playerBody={x:player.x,z:player.z,radius:.45};v.people?.update(stepDt,[...v.animals.map(a=>a.agent),playerBody]);const peers=v.animals.map(a=>a.agent).concat(others,playerBody);for(const a of v.animals){const m=updateAgent(a.agent,stepDt,(x,z)=>rectBlocked(v.plan.blocks,x,z,.05),peers);a.g.position.set(a.agent.x,.2,a.agent.z);a.g.rotation.y=a.agent.heading;a.walkPhase+=m.moved*6;setAnimalMotion(a,m.moved?'walk':a.agent.mode==='graze'?'eat':'idle',m.moved/stepDt);a.mixer?.update(stepDt);animateRigDetails(a,stepDt);a.animateBird?.(stepDt,m.moved>0,a.agent.mode==='graze');}
  }
 }};
}
